package com.example.geosamplemanager.data.voice

import com.google.gson.Gson

/**
 * Сборщик JSON-грамматики для Vosk.
 *
 * Грамматика — это список слов, которые Vosk может распознать.
 * Всё, что не в списке, заменяется на [unk].
 *
 * Зачем: маленькая модель Vosk путается между похожими словами.
 * Ограничение словаря повышает точность на числах и командах.
 *
 * FIX 5.8.6-4:
 * - добавлены слова выбора действия: «снять», «отложить», «пропустить»;
 * - добавлены слова русского веса: «целых», «десятых», «сотых»,
 *   «половиной», «четвертью», «полтора», «полкило»;
 * - добавлены служебные команды, которые раньше могли уходить в поиск;
 * - сохранены числа, порядковые, разделители и [unk].
 */
object VoiceGrammar {

    /**
     * Явные слова команд.
     *
     * Часть слов может отсутствовать в VoiceDictionary, поэтому держим
     * их отдельно. Дубликаты безопасно удаляются через LinkedHashSet.
     */
    private val explicitCommandWords = listOf(
        // ------------------------------------------------------------
        // Отметки
        // ------------------------------------------------------------
        "все",
        "отметь",
        "отметить",
        "отметьте",

        "эту",
        "ее",
        "её",
        "найденную",
        "найденное",

        // ------------------------------------------------------------
        // Режимы
        // ------------------------------------------------------------
        "сортировка",
        "сортировки",
        "сортировку",
        "поиск",
        "режим",

        // ------------------------------------------------------------
        // Управление сессией
        // ------------------------------------------------------------
        "стоп",
        "хватит",
        "пауза",
        "паузу",
        "продолжить",
        "продолжай",

        "отмена",
        "отменить",
        "верни",
        "назад",

        "повтори",
        "вперёд",
        "вперед",

        "следующая",
        "следующий",
        "следующую",
        "далее",

        "помощь",
        "команда",
        "команды",

        // ------------------------------------------------------------
        // Статистика и фильтры
        // ------------------------------------------------------------
        "сколько",
        "осталось",
        "показать",
        "отложенные",
        "найденные",

        // ------------------------------------------------------------
        // Снятие отметок
        // ------------------------------------------------------------
        "снять",
        "сними",
        "убрать",
        "убери",
        "удали",
        "удалить",

        "отметку",
        "пробу",
        "последнюю",
        "отложенную",

        "сбросить",
        "очистить",

        // ------------------------------------------------------------
        // Выбор действия для уже отмеченной / отложенной пробы
        // ------------------------------------------------------------
        "отложить",
        "отложи",
        "перенести",
        "перенеси",

        "пропустить",
        "пропусти",
        "дальше",

        "не",
        "надо",
        "ничего",
        "оставить",
        "потом",

        // ------------------------------------------------------------
        // Русский вес
        // ------------------------------------------------------------
        "вес",

        // Союзы/предлоги для фраз: «два и шесть», «два с половиной».
        "и",
        "с",

        "целых",
        "целая",
        "целое",

        "десятых",
        "десятая",
        "десятые",

        "сотых",
        "сотая",
        "сотые",

        "тысячных",
        "тысячная",
        "тысячные",

        "половиной",
        "четвертью",

        "полтора",
        "полторы",
        "полкило",

        "кг",
        "кило",
        "килограмм",
        "килограмма",
        "килограммы"
    )

    /**
     * Собрать грамматику.
     *
     * @param extra дополнительные слова, например пользовательские
     *              префиксы участков.
     */
    fun build(extra: Collection<String> = emptyList()): String {
        val words = LinkedHashSet<String>(768)

        // Числительные — все формы.
        words.addAll(VoiceDictionary.singleDigits.keys)
        words.addAll(VoiceDictionary.teens.keys)
        words.addAll(VoiceDictionary.tens.keys)
        words.addAll(VoiceDictionary.hundreds.keys)
        words.addAll(VoiceDictionary.thousandWords)
        words.addAll(VoiceDictionary.millionWords)
        words.addAll(VoiceDictionary.zeroWords)

        // Порядковые: первая … тридцатая.
        words.addAll(VoiceOrdinals.map.keys)

        // Разделители: «и», «запятая», «точка» и т.п., если есть в словаре.
        words.addAll(VoiceDictionary.separators)

        // Команды из общего словаря.
        words.addAll(VoiceDictionary.commands)

        // Явные слова команд и новых голосовых сценариев.
        words.addAll(explicitCommandWords)

        // Дополнительные слова от вызывающей стороны.
        words.addAll(extra)

        // Обязательный маркер неизвестного слова.
        // Без него Vosk пытается «впихнуть» шум в распознаваемый словарь.
        words.add("[unk]")

        return Gson().toJson(words.toList())
    }
}
